    else if (ch === '[') { countStack.push(number); stringStack.push(current); current = ''; number = 0; }
    else if (ch === ']') { const repeat = countStack.pop(); const previous = stringStack.pop(); current = previous + current.repeat(repeat); }
    else current += ch;
  }
  return current;
}
